"""One-off generator for data/products.json (GymScope batch 1, Oct 11 2026).
Kept in the repo as the record of how scores were set; edit products.json directly afterwards.

Data comes from each Amazon.com listing (spec table + bullets + review page) captured on Oct 11 2026.
Prices are stored only to place each model in a broad price band — the site never shows an exact price.
"""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
D = "2026-10-11"
TAG = "gymscope00-20"


def clamp(x):
    return max(0, min(10, round(x)))


def formula(s):
    inc = s.get("incline_max_pct") or 0
    inc_score = 0 if not inc else clamp(inc / 15 * 10 - (0 if s.get("auto_incline") else 1.5))
    L, W = s.get("belt_len_in"), s.get("belt_wid_in")
    deck = clamp((L * W - 500) / 600 * 10) if L and W else None
    return {"incline": inc_score, "deck": deck}


BASE = dict(motor_hp=None, brushless=None, speed_min_mph=None, speed_max_mph=None, incline_max_pct=None, auto_incline=False,
            incline_type="None (flat)", belt_len_in=None, belt_wid_in=None, max_user_lb=None, cushioning=None, footprint=None,
            folded=None, weight_lb=None, handrail=None, assembly=None, display=None, app=None, programs=None, remote=None,
            noise_db=None, warranty=None)


def R(author, stars, date, text):
    return {"author": author, "stars": stars, "date": date, "title": None, "excerpt": text, "paraphrase": True}


def bd(a, b, c, d, e):
    return {"5": a, "4": b, "3": c, "2": d, "1": e}


P = []


def add(id, asin, name, short, brand, model, images, tags, seller, price, list_price, avail, rating, count, breakdown,
        specs, extra, sources, edit, ed, featured=False, badge=None, data_note=None, review_note=None):
    sp = dict(BASE)
    sp.update(specs)
    sc = formula(sp)
    sc.update(edit)
    P.append({"id": id, "asin": asin, "name": name, "short": short, "brand": brand, "model": model, "variant": None,
              "affiliate_url": f"https://www.amazon.com/dp/{asin}?tag={TAG}", "affiliate_tag": TAG,
              "canonical_url": f"https://www.amazon.com/dp/{asin}", "images": images.split(), "tags": tags,
              "featured": featured, "badge": badge, "seller": seller, "price": price, "list_price": list_price,
              "price_date": D, "availability": avail, "rating": rating, "reviews_count": count,
              "rating_breakdown": breakdown, "specs": sp, "specs_extra": extra, "spec_sources": sources,
              "data_note": data_note, "review_note": review_note, "scores": sc, "editorial": ed})


AMZ = "Amazon.com"
SRC = "Amazon listing (spec table and product bullets), checked Oct 11 2026."

